/* Blackjack Bot service worker — generated by scripts/build-sw.mjs. */
const VERSION = '__VERSION__';
const CACHE = `bjbot-${VERSION}`;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      // Add in small batches so one slow file doesn't stall the whole install on a phone.
      for (let i = 0; i < PRECACHE.length; i += 20) {
        await cache.addAll(PRECACHE.slice(i, i + 20));
      }
    }),
  );
  // No skipWaiting here: the page shows "Update ready" and the player chooses when (never mid-hand).
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('bjbot-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

function pageUrl(url) {
  // "/learn" → "/learn/" to match exported trailing-slash routes.
  if (!url.pathname.endsWith('/') && !url.pathname.split('/').pop().includes('.')) return url.pathname + '/';
  return url.pathname;
}

async function fromCache(request, pathname) {
  const cache = await caches.open(CACHE);
  return (
    (await cache.match(pathname ?? request, { ignoreSearch: true })) ||
    (await caches.match(pathname ?? request, { ignoreSearch: true }))
  );
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Home-server API (Mac sync): always straight to the network, never cached or faked offline.
  if (url.pathname.startsWith('/api/')) return;

  // Pages: network first (fresh deploys), cached copy when offline or slow.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const path = pageUrl(url);
        try {
          const controller = new AbortController();
          const timer = setTimeout(() => controller.abort(), 3500);
          const res = await fetch(request, { signal: controller.signal });
          clearTimeout(timer);
          if (res.ok) {
            const cache = await caches.open(CACHE);
            cache.put(path, res.clone());
          }
          return res;
        } catch {
          return (await fromCache(request, path)) || (await fromCache(request, '/')) || Response.error();
        }
      })(),
    );
    return;
  }

  // Everything else (JS/CSS chunks, RSC payloads, icons): cache first, then network.
  event.respondWith(
    (async () => {
      const cached = await fromCache(request, url.pathname);
      if (cached) return cached;
      try {
        const res = await fetch(request);
        if (res.ok && url.pathname.startsWith('/_next/')) {
          const cache = await caches.open(CACHE);
          cache.put(url.pathname, res.clone());
        }
        return res;
      } catch {
        return Response.error();
      }
    })(),
  );
});
